/* Project-scoped authoring, script association, shot review and real media binding. */
'use strict';
// Audition one voice at a time; do not let two character samples mask each other.
document.addEventListener('play', (event) => {
  if (!(event.target instanceof HTMLAudioElement)) return;
  document.querySelectorAll('audio').forEach((player) => { if (player !== event.target) player.pause(); });
}, true);
const Creator = window.Creator = {
  view:'boards', workspaces:[], script:null, selectedBlock:null, resourceKind:'all', resourceQuery:'',
  reviews:new Map(), reviewData:null, reviewShot:null, reviewEpoch:0, booting:true, projectEpoch:0,
};
const audioRoles={voice_identity:'音色身份',dialogue_performance:'台词表演',ambience:'环境声',music:'音乐',lip_sync_driver:'口型驱动'};
const usageLabels={model_reference:'模型参考',voice_identity:'音色身份',post_mix:'后期混音',context:'文字上下文'};
const speechModels=()=> (state.models.speech||[]).filter(m=>m.backend==='minimax_tts'&&['speech-2.8-hd','speech-2.8-turbo'].includes(m.model_name||modelId(m)));
const reviewLabels={approved:'已通过',changes_requested:'需修改',unreviewed:'未审阅'};
Object.assign(kindLabels,audioRoles,{reference:'画面参考',text:'文字',prop_spec:'道具规范',context:'文字上下文'});
const allShots=()=>state.project?.shots||[];
const fullShot=id=>allShots().find(s=>s.id===id)||shotBy(id);
const videoNode=id=>state.graph?.nodes.find(n=>n.shotId===id&&['video','reuse','edit'].includes(n.type));
const mediaType=a=>a?.mediaType||a?.kind||'image';
const readStatus=shot=>Creator.reviews.get(shot.id)?.status||shot.review?.status||shot.reviewStatus||'unreviewed';
function closeInspector(){Creator.editorSave=null;document.querySelector('.inspector').classList.remove('is-open');state.selected=null;state.selectedAsset=null;state.selectedEdge=null;$$('.graph-node.selected').forEach(n=>n.classList.remove('selected'));}
function openInspector(){document.querySelector('.inspector').classList.add('is-open');}
function dialogClose(e){e.currentTarget.closest('dialog')?.close();}
function emptyView(title,copy,action,label){const wrap=el('div','empty-view');wrap.append(el('h2','',title),el('p','',copy));if(action)wrap.append(button(label,'primary',action));return wrap;}
function appendScriptText(target,text){const pattern=/\*\*([^*]+)\*\*|`([^`]+)`/g;let start=0;for(const match of text.matchAll(pattern)){target.append(document.createTextNode(text.slice(start,match.index)));target.append(el(match[1]?'strong':'code','',match[1]||match[2]));start=match.index+match[0].length;}target.append(document.createTextNode(text.slice(start)));}
function currentScopeShots(){return allShots().filter(s=>!state.scene||(s.sceneId||s.scene)===state.scene);}
function refreshProjectLabels(){const w=Creator.workspaces.find(w=>w.id===state.workspaceId);const name=w?.name||state.project?.title||'未命名项目';$('#workspaceName').textContent=name;$('#allNodeCount').textContent=Creator.view==='nodes'?(state.graph?.nodes.length||0):allShots().length;$('#allScenes span:first-child').textContent=Creator.view==='nodes'?'全片节点':'全部镜头';$('#resourceCount').textContent=Creator.view==='nodes'?`${state.assets.length} 资源`:`${allShots().length} 镜头`;$('#projectSubtitle').textContent=name;document.title=`${name} · 灵镜AI`;$('#viewContext').textContent=state.scene?(sceneGroups().find(s=>s.id===state.scene)?.name||state.scene):`${allShots().length} 个镜头`;}
function chooseView(view){if(window.ProductionController&&!window.ProductionController.close())return;Creator.view=view;document.body.dataset.view=view;$$('.view-tabs [data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$('#creativeToolbar').hidden=view==='nodes';$('#graphView').hidden=view!=='nodes';['script','boards','resources'].forEach(v=>$(`#${v}View`).hidden=v!==view);$('#libraryTitle').textContent=view==='nodes'?'项目资源':'项目镜头';$('#reviewModeBtn').hidden=view!=='boards';$('#voiceDesignBtn').hidden=view!=='resources';$('#viewTitle').textContent={script:'剧本',boards:'分镜',resources:'资源',nodes:'节点'}[view];$('#viewActionBtn').textContent=view==='resources'?'导入资源':view==='script'?'导入剧本':'新建镜头';closeInspector();refreshProjectLabels();if(view==='boards')renderBoards();if(view==='resources')renderResources();if(view==='script')renderScript();if(view==='nodes'){if(state.graph){renderGraph();requestAnimationFrame(fitCanvas);}else $('#scopeStats').textContent='正在打开项目…';}}

async function bootCreator(){document.body.classList.add('is-loading');try{const catalog=await api('/api/workspaces');Creator.workspaces=catalog.workspaces||[];const requested=new URLSearchParams(location.search).get('workspace');const remembered=Creator.workspaces.some(w=>w.id===requested)?requested:localStorage.getItem('studio.workspace');state.workspaceId=Creator.workspaces.some(w=>w.id===remembered)?remembered:catalog.activeWorkspaceId||Creator.workspaces[0]?.id;if(!state.workspaceId){renderWorkspaceList();$('#workspaceDialog').showModal();$('#boardsView').append(emptyView('还没有项目','每个项目拥有独立的剧本、镜头、资源与生成记录。',()=>$('#workspaceDialog').showModal(),'创建项目'));return;}await openWorkspace(state.workspaceId,false);}catch(e){$('#boardsView').replaceChildren(emptyView('无法打开项目库',e.message,()=>bootCreator(),'重新连接'));toast(e.message,true);}finally{Creator.booting=false;document.body.classList.remove('is-loading');}}
async function openWorkspace(id,activate=true){if(window.ProductionController&&!window.ProductionController.close())return;if(state.switching||state.busy||state.saving||state.uploading||Creator.mutating)return;const previous=state.workspaceId;if(state.dirty&&!confirm('当前节点图有未保存更改。切换项目会放弃这些更改，是否继续？'))return;state.switching=true;document.body.classList.add('is-loading');Creator.projectEpoch++;const epoch=Creator.projectEpoch;closeInspector();closeReview();try{if(activate)await api(`/api/workspaces/${encodeURIComponent(id)}/activate`,{method:'POST',body:'{}'});state.workspaceId=id;localStorage.setItem('studio.workspace',id);const address=new URL(location.href);address.searchParams.set('workspace',id);if(!Creator.booting)address.searchParams.delete('shot');history.replaceState(null,'',address);state.graph=null;state.project=null;state.assets=[];state.jobs=[];state.selected=null;state.selectedAsset=null;state.selectedEdge=null;state.compiled=null;state.preparedRun=null;state.uncertainRun=null;state.dirty=false;state.scene='';state.shot=Creator.booting?(new URLSearchParams(location.search).get('shot')||''):'';state.validation.clear();state.layoutKey=null;state.viewPositions.clear();textPreviewCache.clear();Creator.reviews.clear();Creator.selectedBlock=null;Creator.script=null;$('#boardsView').replaceChildren(el('p','creator-loading','正在打开项目…'));await load();if(epoch!==Creator.projectEpoch)return;if(!state.project)throw new Error('项目数据加载失败');await refreshScript();refreshProjectLabels();chooseView(Creator.view);closeInspector();$('#workspaceDialog').close();}catch(e){toast(`打开项目失败：${e.message}`,true);if(!state.graph)state.workspaceId=previous;}finally{state.switching=false;document.body.classList.remove('is-loading');}}
async function showWorkspaces(){try{const catalog=await api('/api/workspaces');Creator.workspaces=catalog.workspaces||[];renderWorkspaceList();$('#workspaceDialog').showModal();}catch(e){toast(e.message,true);}}
function renderWorkspaceList(){const list=$('#workspaceList');list.replaceChildren();Creator.workspaces.forEach(w=>{const b=el('button',`workspace-row${w.id===state.workspaceId?' current':''}`),info=el('div');info.append(el('strong','',w.name),el('small','',`${w.shotCount??'—'} 镜 · ${w.root||w.projectPath||w.id}`));b.append(el('span','','▤'),info);if(w.id===state.workspaceId)b.append(el('span','current-label','当前项目'));b.onclick=()=>openWorkspace(w.id,true);list.append(b);});if(!Creator.workspaces.length)list.append(el('p','field-help','还没有项目。'))}

function shotAssets(shot){const node=videoNode(shot.id);const ids=new Set((node?.data?.bindings??shot.bindings??[]).filter(b=>b.enabled!==false).map(b=>b.assetId));if(node){(node.data?.bindings||[]).filter(b=>b.enabled!==false).forEach(b=>ids.add(b.assetId));const visited=new Set();function collect(id){if(visited.has(id))return;visited.add(id);state.graph.edges.filter(e=>e.target===id).forEach(e=>{const source=nodeBy(e.source);if(source?.assetId)ids.add(source.assetId);else if(source)collect(source.id);});}collect(node.id);}return state.assets.filter(a=>ids.has(a.id));}
function bestShotMedia(shot){const node=videoNode(shot.id),job=state.jobs.find(j=>node&&(j.workflowNodeId||j.nodeId)===node.id&&j.kind!=='audio'&&j.mediaUrl&&!j.validationOnly);if(job)return{url:safeUrl(job.mediaUrl),thumb:safeUrl(job.thumbnailUrl),kind:job.kind||'video',label:'生成素材 · 待内容审核'};if(shot.mediaUrl&&!shot.validationOnly)return{url:safeUrl(shot.mediaUrl),thumb:safeUrl(shot.thumbnailUrl),kind:shot.mediaKind||'video',label:'已有素材'};const assets=shotAssets(shot).filter(a=>mediaType(a)==='image'&&a.mediaUrl);const a=assets.find(a=>['storyboard','first_frame','result'].includes(a.role))||assets.find(a=>a.role==='environment')||assets[0];return a?{url:safeUrl(a.mediaUrl),thumb:safeUrl(a.thumbnailUrl),kind:'image',label:node?.type==='reuse'?'复用来源参考 · 等待视频':'画面参考 · 视频待制作',asset:a}:{url:'',kind:'image',label:shot.generationMode==='reuse'?'等待批准的复用素材':'还没有画面素材'};}
function visualElement(media,controls=false){if(!media.url)return null;const video=media.kind==='video'||/\.(mp4|webm|mov)(?:\?|$)/i.test(media.url);if(video&&controls){const e=el('video');e.src=media.url;e.controls=true;e.preload='metadata';e.playsInline=true;if(media.thumb)e.poster=media.thumb;return e;}if(video&&!media.thumb){const e=el('video');e.src=media.url;e.muted=true;e.preload='metadata';return e;}const e=el('img');e.src=media.thumb||media.url;e.alt=media.asset?.name||media.label||'镜头画面';e.loading='lazy';e.draggable=false;return e;}
function renderBoards(){const view=$('#boardsView');view.replaceChildren();if(!allShots().length){view.append(emptyView('还没有镜头','导入剧本后，选中一个段落创建镜头。你也可以直接新建镜头。',()=>chooseView('script'),'打开剧本'));return;}const groups=sceneGroups().filter(g=>!state.scene||g.id===state.scene);groups.forEach(group=>{const heading=el('h2','board-scene-heading',group.name);heading.append(el('span','',`${group.shots.length} 镜`));view.append(heading);const grid=el('div','board-grid');group.shots.forEach(summary=>{const shot=fullShot(summary.shotId||summary.id),media=bestShotMedia(shot),card=el('article',`board-card${state.shot===shot.id?' selected':''}`);card.tabIndex=0;card.setAttribute('aria-label',`${shot.id} ${shot.title}，打开审阅`);const picture=el('div','board-media'),visual=visualElement(media);if(visual)picture.append(visual);else picture.append(el('div','no-media',media.label));picture.append(el('span','board-number',shot.id),el('span','board-media-caption',media.label));const copy=el('div','board-content');copy.append(el('h3','',shot.title),el('p','',shot.action||'尚未填写画面动作'));const meta=el('div','board-meta');meta.append(el('span','',shot.shotType||shot.camera||'镜头待设定'),el('span','',`${shot.plannedDuration||'—'} 秒`),el('span',`status-${readStatus(shot)}`,reviewLabels[readStatus(shot)]||'未审阅'));copy.append(meta);card.append(picture,copy);card.onclick=()=>openReview(shot.id);card.onkeydown=e=>{if(e.key==='Enter')openReview(shot.id);};grid.append(card);});view.append(grid);});}

async function refreshScript(){try{Creator.script=await api('/api/script');}catch(e){Creator.script={text:state.project?.script||'',blocks:[],scenes:[],revision:state.project?.revision};if(Creator.script.text)Creator.script.blocks=Creator.script.text.split(/\n\s*\n/).map((text,i)=>({id:`local-${i}`,text,type:/^#/.test(text)?'heading':'paragraph',shotIds:allShots().filter(s=>text.includes(s.id)).map(s=>s.id),localOnly:true}));}}
function renderScript(){const view=$('#scriptView');view.replaceChildren();const data=Creator.script;if(!data?.text){const empty=emptyView('导入剧本','导入原始剧本，再将段落关联到具体镜头。工作台保留原文，不会将导入操作当作自动分镜。');const editor=el('textarea');editor.placeholder='粘贴剧本原文';editor.rows=12;editor.setAttribute('aria-label','导入剧本原文');empty.classList.add('script-import-area');empty.append(editor,button('导入剧本','primary',()=>importScriptText(editor.value)));view.append(empty);return;}const paper=el('article','script-paper'),head=el('div','script-paper-heading');head.append(el('h2','',state.project.title||'剧本'),el('span','',`${data.blocks?.length||0} 段`));paper.append(head);(data.blocks||[]).forEach(block=>{const heading=/^#{1,2}\s/.test(block.text)||['scene','heading','title'].includes(block.type),sub=/^#{3,6}\s/.test(block.text);const b=el('div',`script-block${heading?' heading':sub?' subheading':''}${Creator.selectedBlock===block.id?' selected':''}`,String(block.text||'').replace(/^#{1,6}\s/,''));b.replaceChildren();appendScriptText(b,String(block.text||'').replace(/^#{1,6}\s/gm,''));b.dataset.blockId=block.id;b.tabIndex=0;const links=el('div','block-shot-links');(block.shotIds||[]).forEach(id=>links.append(button(id,'',e=>{e?.stopPropagation?.();const shot=fullShot(id);if(shot){state.scene=shot.sceneId||shot.scene;state.shot=id;renderNavigation();openReview(id);}})));if(links.childElementCount)b.append(links);b.onclick=e=>{if(e.target.closest('button'))return;Creator.selectedBlock=block.id;$$('.script-block').forEach(x=>x.classList.toggle('selected',x.dataset.blockId===block.id));renderScriptContext();};b.onkeydown=e=>{if(e.key==='Enter')b.click();};paper.append(b);});const context=el('aside','script-context');context.id='scriptContext';view.append(paper,context);renderScriptContext();}
function renderScriptContext(){const panel=$('#scriptContext');if(!panel)return;panel.replaceChildren();const block=Creator.script?.blocks?.find(b=>b.id===Creator.selectedBlock);panel.append(el('h3','',block?'段落与镜头':'从剧本到镜头'));if(!block){panel.append(el('p','','选择一段剧本，查看它对应的镜头，或从这段文字建立新的镜头单元。'));return;}panel.append(el('p','',block.text.slice(0,550)));const ids=block.shotIds||[];ids.forEach(id=>{const shot=fullShot(id);if(!shot)return;const row=el('div','linked-shot');row.append(el('strong','',`${id} · ${shot.title}`),el('small','',shot.action||''),button('审阅镜头','secondary',()=>openReview(id)));panel.append(row);});panel.append(button('从此段创建镜头','primary',()=>openNewShot(block)),button('关联到当前镜头','secondary',async()=>{if(!state.shot)return toast('请先在左侧选择一个镜头',true);if(block.localOnly)return toast('请先重新导入剧本以生成稳定的段落编号',true);const shot=fullShot(state.shot);await patchShot(shot.id,{sourceBlockIds:[...new Set([...(shot.sourceBlockIds||[]),block.id])]});await refreshScript();renderScriptContext();}));}
async function importScriptText(text,filename='script.md'){if(!text.trim())return toast('请输入剧本原文',true);try{await api('/api/script/import',{method:'POST',body:JSON.stringify({text,filename,revision:state.project?.revision})});await reloadProjectData();await refreshScript();renderScript();toast('剧本原文已导入');}catch(e){toast(e.message,true);}}
function openScriptImport(){let d=$('#scriptImportDialog');if(d)d.remove();d=el('dialog');d.id='scriptImportDialog';d.style.width='720px';d.append(el('h2','','导入剧本原文'),el('p','','原文会保存在当前项目。镜头关联在导入后单独建立。'));const text=el('textarea');text.rows=15;text.value=Creator.script?.text||'';text.setAttribute('aria-label','剧本原文');let filename='script.md';const picker=el('input');picker.type='file';picker.accept='.md,.txt,text/plain,text/markdown';picker.hidden=true;picker.onchange=async()=>{const file=picker.files[0];if(file){text.value=await file.text();filename=file.name;}};d.append(button('选择剧本文件','secondary',()=>picker.click()),picker,text);const actions=el('div','dialog-actions');actions.append(button('取消','secondary',()=>d.close()),button('导入原文','primary',async()=>{await importScriptText(text.value,filename);d.close();}));d.append(actions);document.body.append(d);d.showModal();}
function openNewShot(block=null){const select=$('#newShotScene');select.replaceChildren();const empty=el('option','','新场次 / 未分类');empty.value='';select.append(empty);sceneGroups().forEach(s=>{const o=el('option','',s.name);o.value=s.id;select.append(o);});select.value=state.scene||'';const form=$('#newShotForm');form.elements.title.value='';form.elements.action.value=block?block.text.replace(/^#+\s*/, ''):'';form.dataset.sourceBlock=block&&!block.localOnly?block.id:'';$('#newShotSource').textContent=block?`来源：${block.text.slice(0,100)}`:'可在剧本视图中关联来源段落。';$('#newShotDialog').showModal();}
async function reloadProjectData(){const [p,g,prod,a]=await Promise.all([api('/api/project'),api('/api/workflow'),api('/api/production'),api('/api/assets')]);state.project=p;state.graph=g.workflow||g;state.production=prod;state.assets=a.assets||[];state.assetRevision=a.revision;state.validation.clear();state.dirty=false;state.layoutKey=null;state.viewPositions.clear();renderNavigation();renderAssets();renderGraph();renderQueue();updateSave();refreshProjectLabels();}
async function patchShot(id,changes){if(Creator.mutating)return null;if(state.dirty&&!await saveGraph(false))return null;Creator.mutating=true;try{const result=await api(`/api/shots/${encodeURIComponent(id)}`,{method:'PATCH',body:JSON.stringify({...changes,revision:state.project.revision})});await reloadProjectData();Creator.reviews.delete(id);if(Creator.view==='boards')renderBoards();toast('镜头设置已保存');return result;}catch(e){toast(`保存镜头失败：${e.message}`,true);return null;}finally{Creator.mutating=false;}}

function readinessFlags(readiness){const row=el('div','readiness-flags');if(!readiness||typeof readiness!=='object'){row.append(el('span',`readiness-flag ${readiness==='ready'?'ready':'waiting'}`,readiness==='ready'?'画面依赖已就绪':'画面依赖待确认'));return row;}[['visualReady','画面'],['audioReady','声音'],['deliveryReady','交付']].forEach(([key,label])=>{const ready=readiness[key]===true;row.append(el('span',`readiness-flag ${ready?'ready':'waiting'}`,`${label} · ${ready?(key==='visualReady'?'可生成':'就绪'):'待准备'}`));});return row;}
function describeValue(v){if(v==null)return'';if(typeof v==='string')return v;if(Array.isArray(v))return v.map(x=>typeof x==='string'?x:[x.speaker||x.character||x.role,x.text||x.line||x.content].filter(Boolean).join('：')).filter(Boolean).join('\n');return v.text||v.description||JSON.stringify(v);}
function shotDialogue(shot,plan={}){return describeValue(plan.lines?.length?plan.lines:shot.dialogue||plan.dialogue||shot.sourceData?.lines);}
function renderAudioTracks(container,assets,bindings=[]){const tracks=assets.filter(a=>mediaType(a)==='audio');if(!tracks.length){container.append(el('p','field-help','尚未绑定音频文件。声音计划与实际录制素材分别管理。'));return;}tracks.forEach(a=>{const binding=bindings.find(b=>b.assetId===a.id)||{},role=binding.role||a.role,slot=el('div','audio-slot');slot.append(el('h4','',`${audioRoles[role]||'音频'} · ${a.name}`));const audio=el('audio');const audioUrl=safeUrl(a.mediaUrl);if(audioUrl){audio.src=audioUrl;audio.controls=true;audio.preload='metadata';slot.append(audio);}else slot.append(el('p','field-help','尚未提供实际音频文件'));slot.append(el('p','',usageLabels[binding.usage]||((role==='voice_identity')?'音色参考，不会作为台词音频直接发送':'用途待明确')));container.append(slot);});}
function boundVoices(shot,data={}){const bindings=data.bindings||editableBindings(shot),ids=new Set(bindings.filter(b=>b.enabled!==false&&(b.usage==='voice_identity'||b.role==='voice_identity')).map(b=>b.assetId));return state.assets.filter(a=>ids.has(a.id)&&(a.vendorVoiceId||a.provenance?.vendorVoiceId)&&!['blocked','missing'].includes(a.reviewStatus));}
function appendSpeechActions(section,shot,data){const lines=Array.isArray(data.audioPlan?.lines)?data.audioPlan.lines:[];const cues=lines.filter(line=>typeof line==='object'&&(line.text||line.line||line.content));if(!cues.length)return;section.querySelector('p')?.remove();const voices=boundVoices(shot,data),models=speechModels();cues.forEach((cue,index)=>{const row=el('div','speech-cue');row.append(el('strong','',cue.speaker||cue.character||cue.role||(cue.kind==='narration'?'旁白':cue.kind==='group'?'群声':'对白')),el('p','',cue.text||cue.line||cue.content));if(voices.length&&models.length)row.append(button('生成这一句…','secondary',()=>openSpeechDialog(shot,cue,index,voices)));section.append(row);});if(!voices.length)section.append(el('p','field-help','关联带声音标识的角色音色后，可以逐句生成。音色试听不会被当作正式对白。'));else if(!models.length)section.append(el('p','field-help','当前尚未读到语音模型目录。'));}
function audioJobStatus(){const target=$('#audioJobStatus');if(!target)return;target.replaceChildren();const jobs=state.jobs.filter(j=>j.kind==='audio'&&!['succeeded','success','completed','failed','cancelled'].includes(j.status));jobs.forEach(j=>target.append(el('div','audio-job-line',`${j.name||(j.type==='voice_design'?'角色声音设计':'台词生成')} · ${statuses[j.status]||j.status}`)));target.hidden=!jobs.length;}
function audioSubmissionDialog(title){const dialog=el('dialog');dialog.className='audio-design-dialog';const header=el('div','dialog-heading');header.append(el('h2','',title),button('×','icon-button',()=>dialog.close()));const form=el('form');dialog.append(header,form);dialog.addEventListener('close',()=>dialog.remove());document.body.append(dialog);return{dialog,form};}
