function connectedResources(n){const owners=n.type==='prompt'?state.graph.edges.filter(e=>e.source===n.id&&['video','image'].includes(nodeBy(e.target)?.type)).map(e=>nodeBy(e.target)):[n];const ids=new Set();[n,...owners].forEach(owner=>{(owner.data?.bindings||[]).filter(b=>b.enabled!==false).forEach(b=>ids.add(b.assetId));state.graph.edges.filter(e=>e.target===owner.id).forEach(e=>{const source=nodeBy(e.source);if(source?.assetId)ids.add(source.assetId);});});return state.assets.filter(a=>ids.has(a.id));}
function addGraphBinding(target,asset,edge=null){const owner=target.type==='prompt'?state.graph.edges.map(e=>e.source===target.id?nodeBy(e.target):null).find(n=>['video','image'].includes(n?.type))||target:target;owner.data=owner.data||{};if(!owner.data.bindings?.length)owner.data.bindings=fullShot(owner.shotId)?editableBindings(fullShot(owner.shotId)):connectedResources(owner).map(bindingFrom);if(!owner.data.bindings.some(b=>b.assetId===asset.id))owner.data.bindings.push(bindingFrom(asset));if(edge){edge.role=asset.role||edge.role;edge.usage=defaultUsage(asset);}return owner;}
function mentionToken(owner,asset){const bindings=owner.data?.bindings||[],binding=bindings.find(b=>b.assetId===asset.id),alias=binding?.alias||asset.name;const unique=alias&&bindings.filter(b=>b.enabled!==false&&(b.alias||assetBy(b.assetId)?.name)===alias).length===1;return `@{${unique?alias:asset.id}}`;}
function resourceUsage(n,asset){const owner=n.type==='prompt'?state.graph.edges.filter(e=>e.source===n.id).map(e=>nodeBy(e.target)).find(t=>['video','image'].includes(t?.type))||n:n;return owner.data?.bindings?.find(b=>b.assetId===asset.id)?.usage||defaultUsage(asset);}
Creator.prettyPrompt=function(n,text){const owner=n.type==='prompt'?state.graph.edges.filter(e=>e.source===n.id).map(e=>nodeBy(e.target)).find(t=>['video','image'].includes(t?.type))||n:n,bindings=owner.data?.bindings||[];return String(text||'').replace(/@\{([^}]+)\}/g,(token,id)=>{const b=bindings.find(b=>b.assetId===id&&b.enabled!==false);if(!b?.alias||b.alias.includes('}'))return token;return bindings.filter(x=>x.enabled!==false&&x.alias===b.alias).length===1?`@{${b.alias}}`:token;});};
function insertMention(input,n,asset){const owner=addGraphBinding(n,asset);if(owner.data.bindings.find(b=>b.assetId===asset.id)?.usage!=='model_reference')return toast('此资源保留在声音或上下文计划中，不插入模型引用');const mention=mentionToken(owner,asset);const start=input.selectionStart??input.value.length,end=input.selectionEnd??start;input.setRangeText(mention,start,end,'end');addGraphBinding(n,asset);input.dispatchEvent(new Event('change',{bubbles:true}));markDirty();input.focus();}
function enhanceNodeInspector(n){const body=$('#inspectorBody');if(!n||!['prompt','image','video','reuse','edit'].includes(n.type))return;const advanced=[...body.querySelectorAll('label')].find(label=>label.textContent.startsWith('模型参数 JSON'));if(advanced){const details=el('details','advanced-params');details.append(el('summary','','高级参数'));advanced.before(details);details.append(advanced);}const upstream=['video','image'].includes(n.type)?state.graph.edges.filter(e=>e.target===n.id&&e.targetPort==='prompt').map(e=>nodeBy(e.source)).find(p=>p?.type==='prompt'):null;const assets=connectedResources(n);const areas=[...body.querySelectorAll('label')].filter(label=>/^提示文本|^节点提示词/.test(label.textContent)).map(label=>label.querySelector('textarea')).filter(Boolean);areas.forEach(input=>{input.value=Creator.prettyPrompt(upstream||n,upstream?nodeText(upstream):input.value);if(upstream){input.readOnly=true;input.rows=3;input.closest('label').after(button('编辑已连接的提示词节点','secondary wide',()=>{chooseView('nodes');selectNode(upstream.id,true);}));return;}const bar=el('div','mention-bar');assets.forEach(a=>{const usage=resourceUsage(n,a);if(usage==='model_reference')bar.append(button(`@ ${a.name}`,'mention-chip',()=>insertMention(input,n,a)));else bar.append(el('span','reference-context-tag',`${usageLabels[usage]||usage} · ${a.name}`));});if(!assets.length)bar.append(el('span','field-help','先连入资源，再用 @ 引用它的身份、画面或声音用途。'));input.closest('label').after(bar);input.addEventListener('keydown',e=>{if(e.key!=='@')return;const existing=body.querySelector('.mention-menu');existing?.remove();if(!assets.length)return;const menu=el('div','mention-menu');assets.filter(a=>resourceUsage(n,a)==='model_reference').forEach(a=>menu.append(button(`${a.name} · ${kindLabels[a.role]||a.role||mediaType(a)}`,'',()=>{if(input.value[input.selectionStart-1]==='@')input.setSelectionRange(input.selectionStart-1,input.selectionStart);insertMention(input,n,a);menu.remove();})));bar.after(menu);});});if(['video','image','reuse','edit'].includes(n.type)){body.append(section('已连接资源的用途'));const list=el('div');if(!n.data.bindings?.length)n.data.bindings=fullShot(n.shotId)?editableBindings(fullShot(n.shotId)):connectedResources(n).map(bindingFrom);renderBindingEditor(list,n.data.bindings,()=>markDirty());body.append(list,el('p','field-help','连线决定资源流向；绑定用途决定发送给模型、保留音色身份，或留作后期。预演会检查未解析引用和模型支持情况。'));}}
const originalRenderInspector=renderInspector;
Creator.assetsChanged=function(){refreshProjectLabels();if(Creator.view==='boards')renderBoards();if(Creator.view==='resources')renderResourceGrid();};
Creator.jobsChanged=audioJobStatus;
Creator.saveCurrent=function(){if(window.ProductionController)return window.ProductionController.save();if(Creator.editorSave&&document.querySelector('.inspector.is-open'))return Creator.editorSave();if(Creator.reviewShot){const notes=$('#reviewStage textarea[aria-label="审阅意见"]');if(notes)return saveReview(Creator.reviewShot,Creator.reviewData?.review?.status||fullShot(Creator.reviewShot)?.review?.status||'unreviewed',notes.value,Creator.reviewData?.projectRevision??state.project?.revision);}return saveGraph();};
const originalRenderQueue=renderQueue;
renderQueue=function(){originalRenderQueue();if(state.queueTab!=='results')return;$$('#queueBody tbody tr').forEach((row,i)=>{const job=state.jobs[i];if(job?.kind==='audio'&&job.mediaUrl){const audio=el('audio');audio.src=safeUrl(job.mediaUrl);audio.controls=true;audio.preload='metadata';audio.style.width='100%';audio.style.height='28px';audio.onclick=e=>e.stopPropagation();row.lastElementChild.replaceChildren(audio);}});};
renderInspector=function(){Creator.editorSave=null;originalRenderInspector();if(state.selectedAsset)Creator.editorSave=[...document.querySelectorAll('#inspectorBody button')].find(b=>b.textContent==='保存资产资料')?.onclick;const n=nodeBy(state.selected);enhanceNodeInspector(n);if(!Creator.booting&&!state.suppressInspector&&(n||state.selectedAsset||state.selectedEdge))openInspector();};
const originalSetScope=setScope;
const originalAddNode=addNode;
addNode=function(type,asset=null){if(Creator.view!=='nodes')chooseView('nodes');originalAddNode(type,asset);openInspector();};
setScope=function(scene,shot=''){originalSetScope(scene,shot);const address=new URL(location.href);if(shot)address.searchParams.set('shot',shot);else address.searchParams.delete('shot');history.replaceState(null,'',address);refreshProjectLabels();if(Creator.view==='boards')renderBoards();if(Creator.view==='script'){const block=Creator.script?.blocks?.find(b=>b.shotIds?.includes(shot));if(block){Creator.selectedBlock=block.id;renderScript();requestAnimationFrame(()=>Array.from(document.querySelectorAll('.script-block')).find(b=>b.dataset.blockId===block.id)?.scrollIntoView({block:'center'}));}}};
const originalConnectPorts=connectPorts;
Creator.edgeRemoved=function(edge){const source=nodeBy(edge.source),target=nodeBy(edge.target);if(!source?.assetId||!target)return;const owner=target.type==='prompt'?state.graph.edges.filter(e=>e.source===target.id).map(e=>nodeBy(e.target)).find(n=>['video','image'].includes(n?.type))||target:target;const stillLinked=state.graph.edges.some(e=>e.target===target.id&&nodeBy(e.source)?.assetId===source.assetId);if(!stillLinked&&owner.data?.bindings)owner.data.bindings=owner.data.bindings.filter(b=>b.assetId!==source.assetId);};
const originalDeleteSelection=deleteSelection;
deleteSelection=function(){const before=[...state.graph.edges];originalDeleteSelection();const remaining=new Set(state.graph.edges.map(e=>e.id));before.filter(e=>!remaining.has(e.id)).forEach(Creator.edgeRemoved);};
connectPorts=function(a,b){const before=state.graph.edges.length;originalConnectPorts(a,b);if(state.graph.edges.length===before)return;const edge=state.graph.edges.at(-1),source=nodeBy(edge.source),target=nodeBy(edge.target),asset=assetBy(source?.assetId);if(!asset||!['prompt','image','video','reuse','edit'].includes(target?.type))return;const scopedAsset={...asset,role:source.data?.role||asset.role};const bindingOwner=addGraphBinding(target,scopedAsset,edge);const addedBinding=bindingOwner.data.bindings.find(b=>b.assetId===asset.id);if(source.data?.usage)addedBinding.usage=source.data.usage;edge.usage=addedBinding.usage;if(addedBinding.usage!=='model_reference'||['reuse','edit'].includes(target.type)){markDirty();renderGraph();renderInspector();return;}const promptNode=target.type==='prompt'?target:state.graph.edges.filter(e=>e.target===target.id&&e.targetPort==='prompt').map(e=>nodeBy(e.source)).find(n=>n?.type==='prompt');const textNode=promptNode||target,key=textNode.type==='prompt'?'text':'prompt',mention=mentionToken(bindingOwner,asset);if(!String(textNode.data[key]||'').includes(mention))textNode.data[key]=`${textNode.data[key]||''}\n${mention}`.trim();markDirty();renderGraph();renderInspector();};
const originalCompile=compile;
compile=async function(ids=scopeNodeIds()){document.querySelector('.queue').hidden=false;await originalCompile(ids);if(state.compiled?.tasks?.length){const task=state.compiled.tasks[0];const bindings=task.referenceBindings||[];if(bindings.length){const body=$('#inspectorBody');body.append(section('实际引用与声音用途'));bindings.forEach(b=>body.append(el('p','field-help',`${b.alias||assetBy(b.assetId)?.name||b.assetId} → ${b.token||b.nativeToken||(b.index!=null?`${kindLabels[b.mediaType]||b.mediaType} ${b.index}`:usageLabels[b.usage]||b.usage)} · ${usageLabels[b.usage]||b.usage}`)));}if(task.unresolvedMentions?.length)$('#inspectorBody').append(el('p','queue-error',`未解析引用：${task.unresolvedMentions.join('、')}`));}};

const voiceDesignButton=button('设计角色声音','secondary',openVoiceDesign);voiceDesignButton.id='voiceDesignBtn';voiceDesignButton.hidden=true;$('#viewActionBtn').before(voiceDesignButton);
$$('.view-tabs [data-view]').forEach(b=>b.onclick=()=>chooseView(b.dataset.view));$('#workspaceBtn').onclick=showWorkspaces;$('#saveBtn').onclick=()=>Creator.saveCurrent();$('#closeInspector').onclick=closeInspector;$('#deleteEdgeBtn').onclick=deleteSelection;$$('[data-close-dialog]').forEach(b=>b.onclick=dialogClose);$('#toggleQueueBtn').onclick=()=>{const q=document.querySelector('.queue');q.hidden=!q.hidden;};$('#viewActionBtn').onclick=()=>Creator.view==='script'?openScriptImport():Creator.view==='resources'?$('#importDialog').showModal():openNewShot();$('#reviewModeBtn').onclick=()=>{const id=state.shot||currentScopeShots()[0]?.id;if(id)openReview(id);else toast('先创建一个镜头');};$('#addShotBtn').onclick=()=>openNewShot();
$('#workspaceForm').onsubmit=async e=>{e.preventDefault();if(state.busy||state.switching||state.uploading)return;const form=e.currentTarget,submit=form.querySelector('[type=submit]');submit.disabled=true;try{const payload=Object.fromEntries(new FormData(form));Object.keys(payload).forEach(k=>{if(!payload[k])delete payload[k];});const result=await api('/api/workspaces',{method:'POST',body:JSON.stringify(payload)});const w=result.workspace||result;const catalog=await api('/api/workspaces');Creator.workspaces=catalog.workspaces||[];form.reset();await openWorkspace(w.id,false);}catch(error){toast(`创建项目失败：${error.message}`,true);}finally{submit.disabled=false;}};
$('#newShotForm').onsubmit=async e=>{e.preventDefault();const form=e.currentTarget;const payload=Object.fromEntries(new FormData(form));payload.sourceBlockIds=form.dataset.sourceBlock?[form.dataset.sourceBlock]:[];if(!payload.sceneId)delete payload.sceneId;try{if(state.dirty&&!await saveGraph(false))return;const result=await api('/api/shots',{method:'POST',body:JSON.stringify(payload)});const shot=result.shot||result;await reloadProjectData();await refreshScript();state.shot=shot.id;state.scene=shot.sceneId||shot.scene||'';renderNavigation();chooseView('boards');$('#newShotDialog').close();toast('镜头已创建');}catch(error){toast(error.message,true);}};
$('#pickFilesBtn').onclick=()=>$('#assetFiles').click();$('#assetFiles').onchange=async e=>{await uploadFiles([...e.target.files]);e.target.value='';};
function allowDrop(surface,onDrop){surface.addEventListener('dragover',e=>{e.preventDefault();surface.classList.add('drop-active');});surface.addEventListener('dragleave',e=>{if(!surface.contains(e.relatedTarget))surface.classList.remove('drop-active');});surface.addEventListener('drop',async e=>{e.preventDefault();surface.classList.remove('drop-active');await onDrop(e);});}
allowDrop($('#uploadDrop'),e=>uploadFiles([...e.dataTransfer.files]));allowDrop($('#resourcesView'),e=>uploadFiles([...e.dataTransfer.files]));allowDrop($('#viewport'),async e=>{const point=localPoint(e),id=e.dataTransfer.getData('application/x-studio-asset');if(id){const a=assetBy(id);if(a){addNode('asset',a);nodeBy(state.selected).position=point;renderGraph();}}else await uploadFiles([...e.dataTransfer.files],point);});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){if(document.querySelector('dialog[open]'))return;if(document.querySelector('.inspector.is-open'))closeInspector();else if(!$('#reviewStage').hidden)closeReview();}if(!$('#reviewStage').hidden&&!e.target.closest('input,textarea,select,audio,video')&&!document.querySelector('dialog[open]')){if(e.key==='ArrowRight')stepReview(1);if(e.key==='ArrowLeft')stepReview(-1);}});
